Next, block helpers + cow_read + cow_write:

```c
/**
 * The number of valid bytes in a block of the export. All blocks
 * hold DIFFPAGESIZE bytes, except for the last one when the export
 * size is not a multiple of DIFFPAGESIZE.
 *
 * @param client the client we're serving
 * @param block the block number we want the size of
 * @return the number of valid bytes in the block
 **/
static size_t cow_blocklen(CLIENT *client, gint64 block) {
	uint64_t start;
	uint64_t left;

	start = (uint64_t)block * DIFFPAGESIZE;
	if(start >= client->exportsize)
		return 0;
	left = client->exportsize - start;
	return left < DIFFPAGESIZE ? (size_t)left : DIFFPAGESIZE;
}
```

```c
/**
 * Find the offset of a block in the copy-on-write diff file.
 * Must be called with client->difmap_lock held.
 *
 * @param client the client we're serving
 * @param block the block number to look up
 * @param doff [out] offset of the block in the diff file
 * @return true if the block is present in the diff file, false if it
 * should be read from the master file instead
 **/
static bool cow_lookup(CLIENT *client, gint64 block, off_t *doff) {
	gint64 *val;

	val = g_hash_table_lookup(client->difmap, &block);
	if(!val)
		return false;
	*doff = (off_t)*val;
	return true;
}
```

```c
/**
 * Record a newly written block in the copy-on-write diff file.
 * Must be called with client->difmap_lock held.
 *
 * @param client the client we're serving
 * @param block the block number to write
 * @param blockoff offset within the block where the write starts
 * @param buf the data to write
 * @param len the amount of data to write; fits within the block
 * @return 0 on success, -1 on failure
 **/
static int cow_store_block(CLIENT *client, gint64 block, off_t blockoff, char *buf, size_t len) {
	char blockbuf[DIFFPAGESIZE];
	size_t blocklen;
	off_t doff;
	ssize_t r;

	blocklen = cow_blocklen(client, block);
	if(cow_lookup(client, block, &doff)) {
		if(pwrite(client->difffile, buf, len, doff + blockoff) != (ssize_t)len)
			return -1;
		return 0;
	}
	if(client->server->flags & F_SPARSE) {
		doff = (off_t)(block * DIFFPAGESIZE);
	} else {
		doff = client->difffilelen;
		client->difffilelen += blocklen;
	}
	if(blockoff != 0 || len != blocklen) {
		/* only part of the block is written; preserve the
		 * rest of its current contents */
		r = rawexpread_master((off_t)(block * DIFFPAGESIZE), blockbuf, blocklen, client);
		if(r < 0)
			return -1;
		if((size_t)r < blocklen)
			memset(blockbuf + r, 0, blocklen - (size_t)r);
		memcpy(blockbuf + blockoff, buf, len);
		if(pwrite(client->difffile, blockbuf, blocklen, doff) != (ssize_t)blocklen)
			return -1;
	} else {
		if(pwrite(client->difffile, buf, len, doff) != (ssize_t)len)
			return -1;
	}
	{
		gint64 *key;
		gint64 *val;

		key = g_new(gint64, 1);
		val = g_new(gint64, 1);
		*key = block;
		*val = doff;
		g_hash_table_insert(client->difmap, key, val);
	}
	return 0;
}
```

