Also `block * DIFFPAGESIZE` — gint64 * int → gint64. The off_t cast is OK.

Next, cow_read:

```c
/**
 * Read from a copy-on-write export. Blocks written during this
 * connection are read back from the diff file; everything else is
 * read from the master file.
 *
 * @param client the client we're serving
 * @param a the offset where the read starts
 * @param buf a buffer to read into
 * @param len the size of buf
 * @return the number of bytes actually read, or -1 in case of error
 **/
static ssize_t cow_read(CLIENT *client, off_t a, char *buf, size_t len) {
	ssize_t ret;
	size_t done;

	ret = rawexpread_master(a, buf, len, client);
	if(ret <= 0)
		return ret;
	pthread_mutex_lock(&client->difmap_lock);
	done = 0;
	while(done < (size_t)ret) {
		gint64 block;
		off_t blockoff;
		off_t doff;
		size_t chunk;

		block = (a + done) / DIFFPAGESIZE;
		blockoff = (a + done) % DIFFPAGESIZE;
		chunk = (size_t)ret - done;
		if(chunk > (size_t)(DIFFPAGESIZE - blockoff))
			chunk = DIFFPAGESIZE - blockoff;
		if(cow_lookup(client, block, &doff)) {
			if(pread(client->difffile, buf + done, chunk, doff + blockoff) != (ssize_t)chunk) {
				pthread_mutex_unlock(&client->difmap_lock);
				return -1;
			}
		}
		done += chunk;
	}
	pthread_mutex_unlock(&client->difmap_lock);
	return ret;
}
```

Hmm, wait, declarations inside the loop body — per the coding style declarations go at the top of the function block; declarations at the top of the while block are also fine ("in all cases, code blocks are shown like so" — declarations are separated within their block). Let me declare them at the top of the while block.

cow_write:

```c
/**
 * Write to a copy-on-write export: the data is recorded in the diff
 * file rather than being written to the master file.
 *
 * @param client the client we're serving
 * @param a the offset where the write starts
 * @param buf the buffer to write from
 * @param len the length of buf
 * @param fua flag to indicate 'Force Unit Access'
 * @return the number of bytes written, or -1 in case of error
 **/
static ssize_t cow_write(CLIENT *client, off_t a, char *buf, size_t len, int fua) {
	size_t done;

	pthread_mutex_lock(&client->difmap_lock);
	done = 0;
	while(done < len) {
		gint64 block;
		off_t blockoff;
		size_t chunk;

		block = (a + done) / DIFFPAGESIZE;
		blockoff = (a + done) % DIFFPAGESIZE;
		chunk = len - done;
		if(chunk > (size_t)(DIFFPAGESIZE - blockoff))
			chunk = DIFFPAGESIZE - blockoff;
		if(cow_store_block(client, block, blockoff, buf + done, chunk) < 0) {
			pthread_mutex_unlock(&client->difmap_lock);
			return -1;
		}
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	pthread_mutex_unlock(&client->difmap_lock);
	return (ssize_t)done;
}
```

Next, the rawexpread dispatcher replacing the original:

```c
ssize_t rawexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	if(client->server->flags & F_COPYONWRITE)
		return cow_read(client, a, buf, len);
	return rawexpread_master(a, buf, len, client);
}
```

