	}
        int newfd;
        if((newfd = open("/dev/null", O_RDWR)) < 0) {
                err("open");
        }
        if(dup2(0, newfd) < 0) {
                err("dup2 stdin");
        }
        if(dup2(1, newfd) < 0) {
                err("dup2 stdout");
        }
        if(dup2(2, newfd) < 0) {
                err("dup2 stderr");
        }
        child=fork();
        if(child < 0) {
                err("fork");
        } else if(child > 0) {
                exit(EXIT_SUCCESS);
        }
	FILE*pidf=fopen(pidfname, "w");
	if(pidf) {
		fprintf(pidf,"%d\n", (int)getpid());
		fclose(pidf);
	} else {
