/**
 * Tear down the copy-on-write state of a client connection. The diff
 * file is removed, so all writes done during the connection are
 * discarded and the master file is left as it was.
 *
 * @param client The client whose copy-on-write state we're destroying
 **/
static void cleanup_cow(CLIENT* client) {
	if(client->difffile >= 0) {
		close(client->difffile);
		client->difffile = -1;
	}
	if(client->difffilename) {
		if(unlink(client->difffilename) < 0) {
			msg(LOG_INFO, "Could not remove copy-on-write diff file %s: %s",
			    client->difffilename, strerror(errno));
		}
		g_free(client->difffilename);
		client->difffilename = NULL;
	}
	if(client->difmap) {
		g_hash_table_destroy(client->difmap);
		client->difmap = NULL;
	}
	pthread_mutex_destroy(&client->difmap_lock);
}

/**
 * Set up copy-on-write for a client connection. All writes done
 * during the connection are recorded in a diff file, so that the
 * master file remains untouched; the diff file is removed again when
 * the connection ends.
 *
 * @param client The client for which to set up copy-on-write
 * @return true on success, false on failure
 **/
static bool setup_cow(CLIENT* client) {
	_cleanup_g_free_ gchar *basedir = NULL;
