	client->difffile = open(client->difffilename, O_RDWR | O_CREAT | O_TRUNC, 0600);
	if(client->difffile < 0) {
		err_nonfatal("Could not open copy-on-write diff file %s: %m", client->difffilename);
		g_free(client->difffilename);
		client->difffilename = NULL;
		return false;
	}
	pthread_mutex_init(&client->difmap_lock, NULL);
	client->difmap = g_hash_table_new_full(g_int64_hash, g_int64_equal, g_free, g_free);
	if(client->server->flags & F_SPARSE) {
		if(ftruncate(client->difffile, (off_t)client->exportsize) < 0) {
			err_nonfatal("Could not size copy-on-write diff file %s: %m", client->difffilename);
			cleanup_cow(client);
			return false;
		}
		client->difffilelen = client->exportsize;
	} else {
		client->difffilelen = 0;
	}
	msg(LOG_INFO, "Recording copy-on-write changes in %s", client->difffilename);
	return true;
}

/**
 * Read an amount of bytes at a given offset from the master file(s),
 * ignoring any copy-on-write diff file. This abstracts the read-side
 * of the multiple files option.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t rawexpread_master(off_t a, char *buf, size_t len, CLIENT *client) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
		return -1;
	if(maxbytes && len > maxbytes)
		len = maxbytes;

	DEBUG("(READ from fd %d offset %llu len %u), ", fhandle, (long long unsigned int)foffset, (unsigned int)len);

	retval = pread(fhandle, buf, len, foffset);
        if (client->server->flags & F_TREEFILES) {
		close(fhandle);
	}
	return retval;
}

/**
 * The number of valid bytes in a block of the export. All blocks
 * hold DIFFPAGESIZE bytes, except for the last one when the export
 * size is not a multiple of DIFFPAGESIZE.
 *
 * @param client The client we're serving for
 * @param block The block number whose size we want
 * @return The number of valid bytes in the block
 **/
static size_t cow_blocklen(CLIENT *client, gint64 block) {
	uint64_t start;
	uint64_t left;

	start = (uint64_t)block * DIFFPAGESIZE;
	if(start >= client->exportsize)
		return 0;
	left = client->exportsize - start;
	return left < DIFFPAGESIZE ? (size_t)left : DIFFPAGESIZE;
}

/**
 * Find the offset of a block in the copy-on-write diff file. Must be
 * called with client->difmap_lock held.
 *
 * @param client The client we're serving for
 * @param block The block number to look up
 * @param doff [out] Offset of the block in the diff file
 * @return true if the block is present in the diff file; false if it
 * is not, in which case its contents must be read from the master
 * file instead
 **/
static bool cow_lookup(CLIENT *client, gint64 block, off_t *doff) {
	gint64 *val;

	val = g_hash_table_lookup(client->difmap, &block);
	if(!val)
		return false;
	*doff = (off_t)*val;
	return true;
}

/**
 * Record a write to a single block in the copy-on-write diff file.
 * Must be called with client->difmap_lock held.
 *
 * @param client The client we're serving for
 * @param block The block number to write
 * @param blockoff Offset within the block where the write starts
 * @param buf The data to write
 * @param len The amount of data to write; guaranteed to fit within
 * the block
 * @return 0 on success, -1 on failure
 **/
static int cow_store_block(CLIENT *client, gint64 block, off_t blockoff, char *buf, size_t len) {
	char blockbuf[DIFFPAGESIZE];
	gint64 *key;
	gint64 *val;
	size_t blocklen;
	off_t doff;
	ssize_t r;

	blocklen = cow_blocklen(client, block);
	if(cow_lookup(client, block, &doff)) {
		/* the diff file already contains this block, so we
		 * can overwrite the relevant part of it */
		if(pwrite(client->difffile, buf, len, doff + blockoff) != (ssize_t)len)
			return -1;
		return 0;
	}
	/* first write to this block; allocate space for it in the
	 * diff file */
	if(client->server->flags & F_SPARSE) {
		doff = (off_t)(block * DIFFPAGESIZE);
	} else {
		doff = client->difffilelen;
		client->difffilelen += blocklen;
	}
	if(blockoff != 0 || len != blocklen) {
		/* only part of the block is written, so preserve the
		 * rest of its current contents */
		r = rawexpread_master((off_t)(block * DIFFPAGESIZE), blockbuf, blocklen, client);
		if(r < 0)
			return -1;
		if((size_t)r < blocklen)
			memset(blockbuf + r, 0, blocklen - (size_t)r);
		memcpy(blockbuf + blockoff, buf, len);
		if(pwrite(client->difffile, blockbuf, blocklen, doff) != (ssize_t)blocklen)
			return -1;
	} else {
		if(pwrite(client->difffile, buf, len, doff) != (ssize_t)len)
			return -1;
	}
	key = g_new(gint64, 1);
	val = g_new(gint64, 1);
	*key = block;
	*val = doff;
	g_hash_table_insert(client->difmap, key, val);
	return 0;
}

/**
 * Read from a copy-on-write export. Blocks that have been written
 * during this connection are read back from the diff file;
 * everything else is read from the master file.
 *
 * @param client The client we're serving for
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @return The number of bytes actually read, or -1 in case of an
 * error
 **/
static ssize_t cow_read(CLIENT *client, off_t a, char *buf, size_t len) {
	ssize_t ret;
	size_t done;

	ret = rawexpread_master(a, buf, len, client);
	if(ret <= 0)
		return ret;
	pthread_mutex_lock(&client->difmap_lock);
	done = 0;
	while(done < (size_t)ret) {
		gint64 block;
		off_t blockoff;
		off_t doff;
		size_t chunk;

		block = (a + done) / DIFFPAGESIZE;
		blockoff = (a + done) % DIFFPAGESIZE;
		chunk = (size_t)ret - done;
		if(chunk > (size_t)(DIFFPAGESIZE - blockoff))
			chunk = DIFFPAGESIZE - blockoff;
		if(cow_lookup(client, block, &doff)) {
			DEBUG("(COW READ from fd %d offset %llu len %u), ", client->difffile, (long long unsigned int)(doff + blockoff), (unsigned int)chunk);
			if(pread(client->difffile, buf + done, chunk, doff + blockoff) != (ssize_t)chunk) {
				pthread_mutex_unlock(&client->difmap_lock);
				return -1;
			}
		}
		done += chunk;
	}
	pthread_mutex_unlock(&client->difmap_lock);
	return ret;
}

/**
 * Write to a copy-on-write export. The data is recorded in the diff
 * file; the master file is left untouched.
 *
 * @param client The client we're serving for
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes written, or -1 in case of an error
 **/
static ssize_t cow_write(CLIENT *client, off_t a, char *buf, size_t len, int fua) {
	size_t done;

	DEBUG("(COW WRITE offset %llu len %u fua %d), ", (long long unsigned)a, (unsigned int)len, fua);

	pthread_mutex_lock(&client->difmap_lock);
	done = 0;
	while(done < len) {
		gint64 block;
		off_t blockoff;
		size_t chunk;

		block = (a + done) / DIFFPAGESIZE;
		blockoff = (a + done) % DIFFPAGESIZE;
		chunk = len - done;
		if(chunk > (size_t)(DIFFPAGESIZE - blockoff))
			chunk = DIFFPAGESIZE - blockoff;
		if(cow_store_block(client, block, blockoff, buf + done, chunk) < 0) {
			pthread_mutex_unlock(&client->difmap_lock);
			return -1;
		}
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	pthread_mutex_unlock(&client->difmap_lock);
	return (ssize_t)done;
}

/**
 * Read an amount of bytes at a given offset from the right file. This
 * abstracts the read-side of the multiple files option. For
 * copy-on-write exports, blocks written during this connection are
 * read back from the diff file.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
ssize_t rawexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	if(client->server->flags & F_COPYONWRITE)
		return cow_read(client, a, buf, len);
	return rawexpread_master(a, buf, len, client);
}

