		CLIENT* client = negotiate(0, servers, &genconf);
		if(!client) {
			exit(EXIT_FAILURE);
		}
		tpool = g_thread_pool_new(handle_request, NULL, genconf.threads, FALSE, NULL);
		mainloop_threaded(client);
		return 0;
	}

	serveloop(servers, &genconf);
}

