		_cleanup_g_free_ gchar *errmsg = NULL;
		errmsg = g_strdup_printf("Could not open copy-on-write diff file %s: %%m", client->difffilename);
		err_nonfatal(errmsg);
		g_free(client->difffilename);
		client->difffilename = NULL;
		return false;
	}
	pthread_mutex_init(&client->difmap_lock, NULL);
